 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                points.setdefault(grid[r][c], []).append((r, c))

    # Each colored marker emits its characteristic ray/endpoint.
    horiz2 = []
    vertical = []
    for color, cells in points.items():
        for r, c in cells:
            if color == 1:
                for dc in (1, 2):
                    if 0 <= c + dc < w:
                        out[r][c + dc] = 5
                if 0 <= r - 1 < h and 0 <= c + 2 < w:
                    out[r - 1][c + 2] = 1
            elif color == 2:
                horiz2.append((r, c - 4, c))
                for x in range(c - 1, c - 4, -1):
                    if 0 <= x < w:
                        out[r][x] = 5
                if 0 <= c - 4 < w:
                    out[r][c - 4] = 2
            elif color == 3:
                vertical.append((r, c, r + 3))
                for y in range(r + 1, r + 3):
                    if 0 <= y < h:
                        out[y][c] = 5
                if 0 <= r + 3 < h:
                    out[r + 3][c] = 3
            elif color == 6:
                vertical.append((r - 6, c, r))
                for y in range(r - 1, r - 6, -1):
                    if 0 <= y < h:
                        out[y][c] = 5
                if 0 <= r - 6 < h:
                    out[r - 6][c] = 6

    # A crossing of a color-2 horizontal ray with a color-3/6 vertical ray
    # becomes color 4 and continues diagonally down-left to the edge.
    for r, left, right in horiz2:
        for top, c, bottom in vertical:
            if left <= c <= right and top <= r <= bottom:
                y, x = r, c
                while 0 <= y < h and 0 <= x < w:
                    out[y][x] = 4
                    y += 1
                    x -= 1

    # Preserve all original markers over ray fills, except a crossing can
    # intentionally replace a marker-path cell with color 4 as demonstrated.
    # The marker positions are otherwise already retained by the copied grid.
    return out
