 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = [(r, c, grid[r][c])
              for r in range(h) for c in range(w) if grid[r][c] != 0]
    horizontal = []
    vertical = []

    for r, c, color in points:
        if color == 1:
            # Two-cell eastward trail, then the 1 marker turns north.
            for x in (c + 1, c + 2):
                if x < w:
                    out[r][x] = 5
            if r > 0 and c + 2 < w:
                out[r - 1][c + 2] = 1
        elif color == 2:
            # Four-cell westward segment, with 2 at its far end.
            left = c - 4
            horizontal.append((r, left, c))
            for x in range(c - 1, left, -1):
                if x >= 0:
                    out[r][x] = 5
            if left >= 0:
                out[r][left] = 2
        elif color == 3:
            # Three-cell southward segment.
            bottom = r + 3
            vertical.append((r, bottom, c))
            for y in range(r + 1, bottom):
                if y < h:
                    out[y][c] = 5
            if bottom < h:
                out[bottom][c] = 3
        elif color == 6:
            # Six-cell northward segment.
            top = r - 6
            vertical.append((top, r, c))
            for y in range(r - 1, top, -1):
                if y >= 0:
                    out[y][c] = 5
            if top >= 0:
                out[top][c] = 6

    # Where a 2-segment crosses a 3/6-segment, mark the crossing and extend
    # a diagonal of 4s down-left to the grid edge.
    for row, left, right in horizontal:
        for top, bottom, col in vertical:
            if left <= col <= right and top <= row <= bottom:
                y, x = row, col
                while y < h and x >= 0:
                    out[y][x] = 4
                    y += 1
                    x -= 1

    return out
